  function field(id, name, subtitle, theme, w = 44, h = 30) {
    const grid = Array.from({ length: h }, (_, y) => Array.from({ length: w }, (_, x) => x < 2 || x >= w - 2 || y < 2 || y >= h - 2 ? 'T' : '.'));
    return { id, name, subtitle, theme, width: w, height: h, grid, npcs: [], exits: [], encounters: [], level: [2,4], spawn: {x:3,y:15} };
  }
  function rect(m, x, y, w, h, c) { for(let j=y;j<y+h;j++) for(let i=x;i<x+w;i++) if(m.grid[j] && m.grid[j][i] !== undefined) m.grid[j][i]=c; }
  function path(m, x1, y1, x2, y2, c = '=') {
    let x=x1,y=y1;m.grid[y][x]=c;
    while(x!==x2){x+=Math.sign(x2-x);m.grid[y][x]=c;}
    while(y!==y2){y+=Math.sign(y2-y);m.grid[y][x]=c;}
  }
  function house(m,x,y,w=5,h=4){rect(m,x,y,w,h,'B');m.grid[y+h-1][x+Math.floor(w/2)]='D';if(y>15){path(m,x+Math.floor(w/2),y+h,x+w+1,y+h);path(m,x+w+1,y+h,x+w+1,15);}else path(m,x+Math.floor(w/2),y+h,x+Math.floor(w/2),15);}
  function flora(m, seed, count, code = '*') {
    for(let i=0;i<count;i++){const x=3+(i*17+seed*13)%(m.width-6),y=3+(i*11+seed*7)%(m.height-6);if(m.grid[y][x]==='.')m.grid[y][x]=code;}
  }
  function npc(m,id,name,x,y,kind,lines,extra={}) { m.npcs.push({id,name,x,y,kind,lines,...extra}); if(m.grid[y][x]==='T'||m.grid[y][x]==='~'||m.grid[y][x]==='#')m.grid[y][x]='.'; }
