  const WALLS = new Set(['T','~','#','B','o']);
  const cardinal = [[1,0],[-1,0],[0,1],[0,-1]];
  const sealOrder = Object.keys(D.guardians);
  function paint(g,x,y,w,h,t) { for(let yy=y;yy<y+h;yy++) for(let xx=x;xx<x+w;xx++) if(g[yy]?.[xx]!==undefined)g[yy][xx]=t; }
  function trace(g,points,t='=') {
    for(let i=1;i<points.length;i++){
      let [x,y]=points[i-1]; const [ex,ey]=points[i];
      const draw=()=>{g[y][x]=g[y][x]==='~'?'b':t;}; draw();
      while(x!==ex){x+=Math.sign(ex-x);draw();} while(y!==ey){y+=Math.sign(ey-y);draw();}
    }
  }
  function house(g,x,y,w=5,h=4) { paint(g,x,y,w,h,'B');g[y+h-1][x+Math.floor(w/2)]='D'; }
  function mapTerrain(kind,index) {
    const g=Array.from({length:30},(_,y)=>Array.from({length:44},(_,x)=>x===0||y===0||x===43||y===29?'T':'.'));
    const island=kind.startsWith('island'), base=kind.replace('island-','');
    if(island){paint(g,0,0,44,30,'~');paint(g,3,3,38,24,'.');paint(g,7,2,29,26,'.');}
    if(['town','port','forge'].includes(base)) {
      paint(g,17,10,12,11,'_');
      [[6,5,6,4],[18,4,7,4],[31,5,6,5],[7,21,7,4],[29,21,8,4]].forEach(a=>house(g,...a));
      trace(g,[[3,15],[39,15]]);trace(g,[[22,8],[22,25]]);
      trace(g,[[9,15],[9,9]]);trace(g,[[34,15],[34,10]]);trace(g,[[10,15],[10,25]]);trace(g,[[33,15],[33,25]]);
      paint(g,4,11,6,3,':');paint(g,31,17,8,3,':');paint(g,15,23,8,3,':');
      if(base==='port') {paint(g,27,2,3,25,'~');trace(g,[[22,15],[38,15]]);trace(g,[[22,23],[33,23]]);}
      if(base==='forge'){paint(g,3,3,2,9,'~');paint(g,39,19,2,7,'~');paint(g,13,5,3,3,'o');}
      if(base==='town'){
        if(index===0){paint(g,14,20,3,6,'T');paint(g,19,22,6,4,'*');trace(g,[[17,19],[26,19],[26,25]]);}
        if(index===7){paint(g,27,3,3,8,'~');paint(g,26,5,1,4,'*');trace(g,[[24,10],[31,10]]);}
        if(index===10){paint(g,18,21,9,2,'o');paint(g,20,23,5,3,':');trace(g,[[17,19],[17,25],[27,25],[27,19]]);}
        if(index===12){paint(g,3,10,3,16,'~');trace(g,[[3,15],[9,15]]);trace(g,[[3,22],[9,22]]);}
      }
    } else if(base==='cave') {
      paint(g,1,1,42,28,'#');
      [[2,11,12,10],[7,3,12,9],[19,8,11,13],[29,3,12,10],[30,19,11,8],[11,22,13,5]].forEach(a=>paint(g,...a,'_'));
      trace(g,[[3,15],[12,15],[12,8],[24,8],[24,16],[36,16],[36,23]],'_');
      trace(g,[[24,16],[18,16],[18,25]],'_');trace(g,[[36,16],[36,8]],'_');
      paint(g,8,4,9,5,':');paint(g,31,4,8,6,':');paint(g,31,20,8,5,':');paint(g,12,23,9,3,':');
      paint(g,21,11,4,4,'~');paint(g,8,17,3,2,'o');
    } else if(base==='ruin') {
      paint(g,1,1,42,28,'_');
      for(let x=7;x<=36;x+=7) {paint(g,x,5,2,5,'#');paint(g,x,20,2,5,'#');}
      paint(g,17,4,11,6,'*');paint(g,17,21,11,5,'~');
      [[3,3,3,7],[33,11,8,3],[3,20,8,7],[30,22,9,4]].forEach(a=>paint(g,...a,':'));
      trace(g,[[2,15],[40,15]],'_');trace(g,[[22,15],[22,7]],'_');trace(g,[[12,15],[12,25]],'_');
      if(index===16){paint(g,29,3,10,6,'~');trace(g,[[27,12],[33,12],[33,6],[38,6]],'_');paint(g,16,11,4,2,'*');}
    } else if(base==='reef'||base==='lake') {
      paint(g,4,3,36,24,'~');
      [[3,11,11,11],[15,3,10,9],[27,11,13,8],[17,22,12,5]].forEach(a=>paint(g,...a,'.'));
      trace(g,[[3,15],[20,15],[20,7],[33,7],[33,15],[33,24],[23,24]],'=');
      trace(g,[[9,15],[9,23],[23,23]]);
      [[5,17,7,3],[16,4,7,5],[29,12,8,4],[19,24,7,2]].forEach(a=>paint(g,...a,':'));
      if(base==='lake'){paint(g,5,5,5,4,'o');paint(g,35,21,4,4,'o');}
    } else if(base==='marsh') {
      paint(g,2,2,40,26,'~');
      [[2,11,11,10],[15,3,10,8],[17,17,11,10],[31,9,10,13]].forEach(a=>paint(g,...a,'.'));
      trace(g,[[3,15],[20,15],[20,7],[35,7],[35,15],[24,15],[24,24],[8,24],[8,15]]);
      [[4,17,6,3],[16,4,7,4],[19,19,7,6],[33,10,6,4]].forEach(a=>paint(g,...a,':'));
    } else if(base==='canyon'||base==='cliff') {
      for(let x=9;x<39;x+=10){paint(g,x,2,4,11,'#');paint(g,x,18,4,10,'#');}
      trace(g,[[2,15],[38,15],[38,7],[15,7]],'_');trace(g,[[8,15],[8,24],[35,24]],'_');
      [[3,3,5,8],[15,3,4,7],[25,20,4,6],[34,19,6,7]].forEach(a=>paint(g,...a,':'));
      paint(g,21,17,3,5,'~');
    } else if(base==='garden') {
      paint(g,14,3,15,7,'~');paint(g,4,21,10,5,'~');
      trace(g,[[2,15],[38,15],[38,24],[20,24],[20,7],[7,7],[7,15]]);
      [[4,3,7,6],[31,3,9,8],[16,19,9,7],[29,20,8,5]].forEach(a=>paint(g,...a,':'));
      paint(g,24,12,6,2,'*');paint(g,10,17,5,2,'*');
    } else {
      // Woodland loops and the meandering river each keep two ways around obstacles.
      for(let y=3;y<27;y++)for(let x=4;x<40;x++) {
        const n=(x*31+y*17+index*23)%41;
        if(n<6)g[y][x]='T';else if(n<23)g[y][x]=':';else if(n===25)g[y][x]='*';
      }
      trace(g,[[2,15],[12,15],[12,8],[31,8],[31,22],[10,22],[10,15],[39,15]]);
      if(base==='river'){
        for(let y=2;y<28;y++){const x=22+Math.floor(Math.sin(y*.35)*3);paint(g,x,y,3,1,'~');}
        trace(g,[[12,8],[31,8]]);trace(g,[[10,22],[31,22]]);trace(g,[[12,15],[39,15]]);
      } else {paint(g,18,11,6,7,'T');paint(g,29,25,5,2,'*');}
    }
    // Distinct local flower and stone groups, away from the arrival corridor.
    const fx=5+(index*7)%30,fy=3+(index*5)%21;
    if(g[fy][fx]==='.')paint(g,fx,fy,2,1,'*');
    trace(g,[[2,15],[7,15]]);
    return g;
  }
  function flood(g,start,npcs=[]) {
    const occupied=new Set(npcs.map(n=>`${n.x},${n.y}`));
    const seen=new Set([`${start.x},${start.y}`]),q=[[start.x,start.y]];
    for(let i=0;i<q.length;i++)for(const [dx,dy] of cardinal){
      const x=q[i][0]+dx,y=q[i][1]+dy,key=`${x},${y}`;
      if(g[y]?.[x]!==undefined&&!WALLS.has(g[y][x])&&!occupied.has(key)&&!seen.has(key)){seen.add(key);q.push([x,y]);}
    }
    return seen;
  }
  // Connect non-building walkable pockets to the path network. Carving happens at
  // construction time, so collision and artwork always share the same tiles.
  function connectAll(g,start) {
    let reachable=flood(g,start);
    for(let y=1;y<29;y++)for(let x=1;x<43;x++){
      if(WALLS.has(g[y][x])||reachable.has(`${x},${y}`))continue;
      const queue=[[x,y]],came=new Map([[`${x},${y}`,null]]);let end=null;
      for(let i=0;i<queue.length&&!end;i++)for(const [dx,dy]of cardinal){
        const nx=queue[i][0]+dx,ny=queue[i][1]+dy,k=`${nx},${ny}`;
        if(nx<1||ny<1||nx>42||ny>28||g[ny][nx]==='B'||came.has(k))continue;
        came.set(k,queue[i]);queue.push([nx,ny]);if(reachable.has(k)){end=[nx,ny];break;}
      }
      if(end){let p=end;while(p){const [px,py]=p;if(WALLS.has(g[py][px]))g[py][px]=g[py][px]==='~'?'b':'=';p=came.get(`${px},${py}`);}reachable=flood(g,start);}
    }
  }
  function placeNpc(map,g,id,name,kind,lines,preferred,extra={}) {
    // Keep every NPC beside a wide, connected approach; never seal a corridor.
    const occupied=new Set(map.npcs.map(n=>`${n.x},${n.y}`));
    const reach=flood(g,map.spawn,map.npcs);
    const candidates=[];
    for(let y=3;y<27;y++)for(let x=5;x<40;x++){
      if(!reach.has(`${x},${y}`)||occupied.has(`${x},${y}`)||map.exits.some(e=>e.x===x&&e.y===y))continue;
      let open=0;for(const[dx,dy]of cardinal)if(reach.has(`${x+dx},${y+dy}`))open++;
      if(open<3)continue;
      candidates.push({x,y,d:Math.abs(x-preferred[0])+Math.abs(y-preferred[1])});
    }
    candidates.sort((a,b)=>a.d-b.d||a.y-b.y||a.x-b.x);
    for(const candidate of candidates){
      const record={id,name,x:candidate.x,y:candidate.y,kind,lines,...extra};
      const next=flood(g,map.spawn,[...map.npcs,record]);
      if(next.size>=reach.size-1){map.npcs.push(record);g[record.y][record.x]='_';return;}
    }
    throw new Error(`No accessible location for ${id}`);
  }
