    if(kind==='station'){rect(g,5,7,33,2,'_');rect(g,5,11,33,2,'_');rect(g,5,20,33,3,':');}
    if(kind==='league'){rect(g,2,2,40,26,'_');for(const x of [8,16,28,36]){rect(g,x,4,2,4,'#');rect(g,x,21,2,5,'#');}rect(g,16,8,13,10,'=');}
