    for(let y=3;y<parent.height-3;y++)for(let x=3;x<parent.width-3;x++)if(seen.hasXY(x,y)&&g[y][x]!=='D'&&!(x===parent.spawn.x&&y===parent.spawn.y)&&cardinal.filter(([dx,dy])=>seen.hasXY(x+dx,y+dy)).length>=3)ports.push({x,y,d:Math.abs(x-(parent.width-5))+Math.abs(y-15)});
    let chosen=null;for(const p of rankedFirst(ports))if(flood(g,parent.spawn,[...obstacles,p]).size>=seen.size-1){chosen=p;break;}if(!chosen)throw Error(`No port ${parent.id}`);
