  oldGuardians.forEach((id,i)=>{D.guardians[id].seal=['芽吹き旅紋','潮音旅紋','深緑旅紋','星環旅紋','陽炎旅紋','氷鏡旅紋','熾火旅紋','黎明旅紋'][i];D.guardians[id].title=D.guardians[id].title.replace('守り手','紋章守');D.guardians[id].region=D.guardians[id].map;});
