      rect(rg,7,4,4,10,'=');rg[14][9]='D';
      const room={id:roomId,name,subtitle:`${labels[roomKind]}の入口は南側。扉を通ると${m.name}へ戻れます。`,theme:m.theme,music:roomKind==='home'?'inn':roomKind,interior:true,parentMap:regionId,roomKind,region:m.region||'星環本土',width:18,height:16,spawn:{x:9,y:12},tiles:[],npcs:[],exits:[],encounters:[],level:m.level.slice(),requiredSeals:m.requiredSeals||0,furniture:[],door:{x:door.x,y:door.y}};
      function furniture(type,x,y,w,h,c='B'){room.furniture.push({type,x,y,w,h});rect(rg,x,y,w,h,c);}
