  // Saves, trades and teams that still name them are converted to a sibling of
  // the same element and stage (see Engine.validate / tradeMonster).
  const RETIRED=Object.freeze({tobine:'tousa',shigureh:'tobari',harune:'nureha',kohakuon:'hotarune',sangoro:'rurihime',lazur:'yashiro'});
  for(const [old,next] of Object.entries(RETIRED)){
    if(!D.species[old]||!D.species[next])throw Error(`Invalid retirement ${old}`);
    delete D.species[old];
    for(const m of Object.values(D.maps))if(m.encounters?.includes(old)){m.encounters=m.encounters.filter(id=>id!==old);if(!m.encounters.includes(next))m.encounters.push(next);}
    for(const group of [D.rivals,D.guardians,D.elites])for(const t of Object.values(group||{})){if(t.species===old)t.species=next;for(const mon of t.team||[])if(mon.species===old)mon.species=next;}
  }
  D.retiredSpecies=RETIRED;

  // ── Species pools for the second continent (evolved forms, starter lines excluded).
  const starterLine=new Set();
  for(const id of D.starters){let s=D.species[id];while(s){starterLine.add(s.id);s=D.species[s.evolvesTo];}}
  const ordinary=Object.values(D.species).filter(s=>!s.specialOnly&&!starterLine.has(s.id)&&s.id!==D.legendary?.species&&s.rarity!=='legendary'&&s.rarity!=='mythical');
