          for(let y=NORTH.y;y<=4;y++)if(K.blocked.has(g[y][NORTH.x])||g[y][NORTH.x]==='D')g[y][NORTH.x]='=';
          m.exits.push({x:NORTH.x,y:NORTH.y,to:dist.stages[0].id,tx:WEST_IN.x,ty:WEST_IN.y,shortcut:true,gate:'north',label:`${dist.stages[0].name}への近道`});
