  for(let x=village.width-3;x>2&&!wall;x--)for(let y=2;y<6&&!wall;y++)if(!K.blocked.has(vg[y][x])&&K.blocked.has(vg[y-1][x])&&!village.npcs.some(n=>n.x===x&&n.y===y)&&!village.exits.some(e=>e.x===x&&e.y===y))wall={map:'village',x,y,dir:'up'};
  if(!wall)throw Error('No glitch wall');
  D.trickWall=Object.freeze(wall);
  const glitch=room('interior-glitch','ﾊﾞｸﾞの裏部屋','壁の向こう側。地図にない部屋。扉を出ると風待ちの里へ戻る。',village,'lab','glitch',{x:wall.x,y:wall.y});
  {
    const gg=glitch.tiles.map(r=>[...r]);
    for(let y=2;y<14;y++)for(let x=2;x<16;x++)if(gg[y][x]==='_'&&(x*7+y*11)%13===0&&!(x>=7&&x<=10))gg[y][x]=(x+y)%3?'o':'~';
    K.connectTerrain(gg,glitch.spawn);glitch.tiles=gg.map(r=>r.join(''));
  }
  const nullTeam=['crystal','ember','tide','wind','leaf','crystal'].map((e,n)=>finalsBy[e][(n*3+2)%finalsBy[e].length]);
  D.rivals['glitch-keeper']={id:'glitch-keeper',name:'裏部屋の番人・ヌル',map:glitch.id,species:nullTeam.at(-1),level:100,reward:9999,
    lines:['ｺｺﾊ…ﾁｽﾞﾆﾅｲ…ﾍﾔ…','……ようこそ。ここは作られなかったはずの部屋。勝てたら、この部屋のことを覚えていていい。'],
    team:nullTeam.map(species=>({species,level:100})),portrait:15,tactic:7,hidden:true};
  K.placeNPC(glitch,{id:'glitch-keeper',name:'裏部屋の番人・ヌル',kind:'rival',rivalId:'glitch-keeper',lines:D.rivals['glitch-keeper'].lines,portrait:15},[9,4]);
  K.placeNPC(glitch,{id:'glitch-note',name:'？？？',kind:'dialogue',lines:['ｦｦｦ……ｽｳｼﾞﾆ ﾅｲ ｶｹﾞｶﾞ ｲﾙ。','一歩も動かず、私に8回続けて話しかけて。図鑑の外側に、言葉のすきまが開く。']},[4,10]);
  K.placeNPC(glitch,{id:'glitch-cache',name:'化けた宝箱',kind:'cache',lines:['ﾀｶﾗﾊﾞｺ……のはずのもの。'],reward:{coins:8888,chime:8,tonic:8}},[14,10]);

  // An unseen keepsake in the first town (south-west corner).
  let spot=null;
  for(let y=village.height-3;y>2&&!spot;y--)for(let x=2;x<8&&!spot;x++)if(!K.blocked.has(vg[y][x])&&!village.npcs.some(n=>n.x===x&&n.y===y)&&!village.exits.some(e=>e.x===x&&e.y===y)&&!(x===village.spawn.x&&y===village.spawn.y))spot={map:'village',x,y};
