        const rival=b.rival?D.rivals[b.rival]:null;
        const leagueBoss=b.elite?D.elites[b.elite]:b.champion?(CHAMPIONS.find(c=>c.id===b.champion)||D.champion):null;
        const coins=leagueBoss?(b.rematch?Math.ceil(leagueBoss.reward*.4):leagueBoss.reward):b.towerFloor?100+b.towerFloor*20:guardian?(b.rematch?Math.ceil(guardian.reward*.4):guardian.reward):rival?rival.reward:18+b.enemy.level*4;
