      if(!this.state.started)return fail('先に旅を始めましょう。');
      const npc=this.nearbyNPC();
      if(!npc || npc.kind!=='rest')return fail('宿や休み場の隣で、休んでください。');
      this.state.party.forEach(mon=>this.restoreMonster(mon));
