      if(!D.items[itemId] || !finiteInt(qty,1,99))return fail('購入する道具と個数を選んでください。');
      const npc=this.nearbyNPC();if(!npc || npc.kind!=='shop')return fail('道具屋の隣で話しかけてください。');
      const cost=D.items[itemId].price*qty;
      if(this.state.inventory[itemId]+qty>999)return fail('これ以上は持ちきれません。');
      if(this.state.coins<cost)return fail('コインが足りません。草むらでの共鳴でも手に入ります。');
