      if(!finiteInt(index,0,this.state.party.length-1))return fail('使う相手を選んでください。');
      if(this.state.inventory[itemId]<=0)return fail(`${D.items[itemId].name}がありません。`);
      const mon=this.state.party[index];
      clearImmuneCondition(mon);
      if(itemId==='remedy')return mon.hp<=0?fail('倒れたパチモンには使えません。'):mon.status?{ok:true}:fail(mon.curse?'呪縛は道具では治せません。':'そのパチモンは状態異常ではありません。');
