      const species=D.species[mon.species];
      if(!Object.hasOwn(D.species,mon.species) || species.specialOnly || species.adminOnly || ['futo','floravelle'].includes(mon.species))throw Error('このパチモンは交換の対象にできません。');
      if(typeof mon.uid!=='string' || !/^[a-zA-Z0-9_-]{1,80}$/.test(mon.uid) || !finiteInt(mon.level,1,MAX_LEVEL) || !finiteInt(mon.xp,0,mon.level===MAX_LEVEL?0:this.xpToNext(mon.level)-1) || !finiteInt(mon.hp,0,this.stats(mon).hp))throw Error('交換するパチモンの能力情報が正しくありません。');
      if(mon.shiny!==undefined && typeof mon.shiny!=='boolean')throw Error('交換するパチモンの色違い情報が正しくありません。');
      const nickname=mon.nickname===undefined?'':normalizeNickname(mon.nickname),moves=this.moves(mon);
      if(!mon.pp || typeof mon.pp!=='object' || Array.isArray(mon.pp) || Object.keys(mon.pp).length!==moves.length || Object.keys(mon.pp).some(id=>!moves.some(move=>move.id===id)))throw Error('交換するパチモンの技情報が正しくありません。');
      const pp={};for(const move of moves){if(!Object.hasOwn(mon.pp,move.id) || !finiteInt(mon.pp[move.id],0,this.maxPP(move)))throw Error('交換するパチモンのPPが正しくありません。');pp[move.id]=mon.pp[move.id];}
      return {uid:mon.uid,species:mon.species,level:mon.level,xp:mon.xp,hp:mon.hp,pp,shiny:mon.shiny===true,...(nickname?{nickname}:{})};
