    // Trades travel in the exchange server's catalog (the movesets from before the
    // 96-move rework); PP is carried slot by slot, keeping its share of the maximum.
    tradeWirePP(mon){
      const pp=mon?.pp,old=D.legacyMovesets?.[mon?.species],ids=D.species[mon?.species]?.moves;
      if(!pp||typeof pp!=='object'||Array.isArray(pp))return pp;
      if(!old||!ids||Object.keys(pp).length!==ids.length||!ids.every(id=>Object.hasOwn(pp,id)))return {...pp};
      return Object.fromEntries(old.map(([id,max],i)=>[id,finiteInt(pp[ids[i]],0,this.maxPP(D.moves[ids[i]]))?scalePP(pp[ids[i]],this.maxPP(D.moves[ids[i]]),max):pp[ids[i]]]));
    }
    toTradeWire(mon){const trade=this.tradeMonster(mon);return {...trade,pp:this.tradeWirePP(trade)};}
    fromTradeWire(wire){
      const old=D.legacyMovesets?.[wire?.species],ids=D.species[wire?.species]?.moves,pp=wire?.pp;
      if(!old||!ids||!pp||typeof pp!=='object'||Array.isArray(pp)||Object.keys(pp).length!==old.length||!old.every(([id])=>Object.hasOwn(pp,id)))return wire;
      return {...wire,pp:Object.fromEntries(ids.map((id,i)=>[id,finiteInt(pp[old[i][0]],0,old[i][1])?scalePP(pp[old[i][0]],old[i][1],this.maxPP(D.moves[id])):-1]))};
    }
